DROP FUNCTION IF EXISTS public.uitgelicht_page_offers(text);
CREATE OR REPLACE FUNCTION public.uitgelicht_page_offers(p_slug text) RETURNS TABLE (page_slug text, dish_name text, "position" int, total int, searches_per_month numeric, places_left int, list_price_cents int, page_kind text, topplek_left int, topplek_price_cents int) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH r AS (SELECT id, city_id FROM public.restaurants WHERE slug = p_slug AND is_active LIMIT 1), pages AS (SELECT p.slug, p.page_kind, s.subject FROM public.seo_landing_pages p, r, LATERAL public.page_subject(p.slug) s WHERE p.city_id = r.city_id AND p.is_active AND p.slug NOT LIKE 'gerecht-%' AND public.uitgelicht_page_eligible(p.slug) AND EXISTS (SELECT 1 FROM public.page_restaurant_ids(p.slug) x WHERE x.restaurant_id = r.id)) SELECT pg.slug, initcap(pg.subject), pos."position", coalesce(pos.total, public.landing_page_restaurant_count(pg.slug)), coalesce((SELECT d.searches_per_month FROM public.uitgelicht_page(pg.slug) g, public.promo_demand(g.city_id, g.dish_id) d WHERE g.dish_id IS NOT NULL), 0), public.founding_places_left(pg.slug), public.pp_list_price('uitgelicht', pg.slug), pg.page_kind, public.topplek_places_left(pg.slug), public.pp_list_price('topplek', pg.slug) FROM pages pg LEFT JOIN public.restaurant_positions(p_slug) pos ON pos.page_slug = pg.slug ORDER BY pg.page_kind = 'dish' DESC, pos."position" NULLS LAST, 1 $$;
REVOKE ALL ON FUNCTION public.uitgelicht_page_offers(text) FROM public;
GRANT EXECUTE ON FUNCTION public.uitgelicht_page_offers(text) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.page_paid_placements(p_page_slug text) RETURNS TABLE (restaurant_id uuid, kind text, is_founding boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT h.restaurant_id, h.kind, h.is_founding FROM (SELECT o.restaurant_id, CASE WHEN bool_or(o.package IN ('topplek', 'dominant')) THEN 'topplek' ELSE 'uitgelicht' END AS kind, bool_or(o.package IN ('founding_partner', 'groei') AND o.created_at <= public.uitgelicht_window_end()) AS is_founding FROM public.package_orders o JOIN public.restaurants r ON r.id = o.restaurant_id AND r.is_active WHERE o.page_slug = p_page_slug AND o.package IN ('founding_partner', 'groei', 'topplek', 'dominant') AND public.founding_partner_live(o.status) GROUP BY o.restaurant_id) h ORDER BY h.kind = 'uitgelicht', md5(h.restaurant_id::text || current_date::text) $$;
GRANT EXECUTE ON FUNCTION public.page_paid_placements(text) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.founding_partners_for_page(p_page_slug text) RETURNS TABLE (restaurant_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT x.restaurant_id FROM public.page_paid_placements(p_page_slug) x $$;
GRANT EXECUTE ON FUNCTION public.founding_partners_for_page(text) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.search_paid_placements(p_city uuid, p_dish_ids uuid[] DEFAULT NULL, p_cuisine text DEFAULT NULL) RETURNS TABLE (restaurant_id uuid, kind text, page_slug text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH wanted AS (SELECT DISTINCT coalesce(d.canonical_slug, d.slug) AS canon, d.dish_group FROM public.dishes d WHERE d.id = ANY (coalesce(p_dish_ids, ARRAY[]::uuid[]))), pages AS (SELECT p.slug FROM public.seo_landing_pages p LEFT JOIN public.dishes d ON d.id = p.dish_id WHERE p.city_id = p_city AND p.is_active AND p.slug NOT LIKE 'gerecht-%' AND ((p.page_kind = 'dish' AND EXISTS (SELECT 1 FROM wanted w WHERE coalesce(d.canonical_slug, d.slug) IN (w.canon, w.dish_group))) OR (p.page_kind = 'cuisine' AND p_cuisine IS NOT NULL AND lower(p.cuisine) = lower(p_cuisine)))) SELECT DISTINCT ON (x.restaurant_id) x.restaurant_id, x.kind, pg.slug FROM pages pg, LATERAL public.page_paid_placements(pg.slug) x ORDER BY x.restaurant_id, x.kind = 'uitgelicht' $$;
GRANT EXECUTE ON FUNCTION public.search_paid_placements(uuid, uuid[], text) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.restaurant_paid_badges(p_restaurant uuid) RETURNS TABLE (page_slug text, kind text, subject text, city_name text, is_founding boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT h.page_slug, h.kind, h.subject, h.city_name, h.is_founding FROM (SELECT o.page_slug, CASE WHEN bool_or(o.package IN ('topplek', 'dominant')) THEN 'topplek' ELSE 'uitgelicht' END AS kind, min(s.subject) AS subject, min(s.city_name) AS city_name, bool_or(o.package IN ('founding_partner', 'groei') AND o.created_at <= public.uitgelicht_window_end()) AS is_founding FROM public.package_orders o, LATERAL public.page_subject(o.page_slug) s WHERE o.restaurant_id = p_restaurant AND o.package IN ('founding_partner', 'groei', 'topplek', 'dominant') AND public.founding_partner_live(o.status) GROUP BY o.page_slug) h ORDER BY h.kind = 'uitgelicht', h.page_slug $$;
GRANT EXECUTE ON FUNCTION public.restaurant_paid_badges(uuid) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.city_landing_pages(p_city uuid) RETURNS TABLE (page_slug text, page_kind text, subject text, restaurant_count int) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.slug, p.page_kind, CASE p.page_kind WHEN 'cuisine' THEN p.cuisine WHEN 'ambience' THEN 'Romantisch' ELSE d.name END, c.restaurant_count FROM public.seo_landing_pages p JOIN public.landing_page_counts c ON c.page_slug = p.slug LEFT JOIN public.dishes d ON d.id = p.dish_id WHERE p.city_id = p_city AND p.is_active AND p.slug NOT LIKE 'gerecht-%' AND c.restaurant_count >= 3 AND (p.page_kind <> 'dish' OR d.canonical_slug IS NULL OR d.canonical_slug = d.slug) ORDER BY c.restaurant_count DESC, 1 $$;
GRANT EXECUTE ON FUNCTION public.city_landing_pages(uuid) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.city_toppleks(p_city uuid) RETURNS TABLE (page_slug text, page_kind text, subject text, restaurant_count int, restaurant_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT cp.page_slug, cp.page_kind, cp.subject, cp.restaurant_count, x.restaurant_id FROM public.city_landing_pages(p_city) cp, LATERAL public.page_paid_placements(cp.page_slug) x WHERE x.kind = 'topplek' ORDER BY cp.restaurant_count DESC $$;
GRANT EXECUTE ON FUNCTION public.city_toppleks(uuid) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.routing_sponsors(p_city uuid, p_dish_ids uuid[]) RETURNS TABLE (restaurant_id uuid, dish_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT DISTINCT s.restaurant_id, m.dish_id FROM public.promo_slots s JOIN public.promo_markets m ON m.id = s.market_id WHERE m.product = 'routing' AND m.city_id = p_city AND m.dish_id = ANY (p_dish_ids) AND s.status IN ('active', 'ending') UNION SELECT DISTINCT o.restaurant_id, p.dish_id FROM public.package_orders o JOIN public.seo_landing_pages p ON p.slug = o.page_slug WHERE o.package = 'dominant' AND public.founding_partner_live(o.status) AND p.city_id = p_city AND p.dish_id = ANY (p_dish_ids) $$;
GRANT EXECUTE ON FUNCTION public.routing_sponsors(uuid, uuid[]) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.restaurant_positions(p_slug text) RETURNS TABLE(page_slug text, dish_name text, "position" integer, total integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH r AS (SELECT id, city_id, coalesce(rating, 0) rt FROM restaurants WHERE slug = p_slug AND is_active = true LIMIT 1), own AS (SELECT DISTINCT d.canonical_slug AS canon, d.dish_group FROM restaurant_dishes rd JOIN dishes d ON d.id = rd.dish_id JOIN r ON r.id = rd.restaurant_id WHERE rd.status IN ('approved_by_admin', 'verified_by_owner')), pages AS (SELECT p.slug AS page_slug, d.name AS dish_name, p.city_id, coalesce(d.canonical_slug, d.slug) AS canon, coalesce(coalesce(d.canonical_slug, d.slug) = d.dish_group, false) AS is_hub FROM seo_landing_pages p JOIN dishes d ON d.id = p.dish_id JOIN r ON r.city_id = p.city_id WHERE p.is_active = true AND p.page_kind = 'dish' AND p.slug NOT LIKE 'gerecht-%' AND (d.canonical_slug IS NULL OR d.canonical_slug = d.slug)), mine AS (SELECT pg.* FROM pages pg WHERE (pg.is_hub AND EXISTS (SELECT 1 FROM own o WHERE o.dish_group = pg.canon)) OR (NOT pg.is_hub AND EXISTS (SELECT 1 FROM own o WHERE o.canon = pg.canon))), comp AS (SELECT pg.page_slug, pg.dish_name, x.id, x.rt FROM mine pg JOIN LATERAL (SELECT DISTINCT rs.id, coalesce(rs.rating, 0) rt FROM restaurant_dishes rd JOIN dishes dd ON dd.id = rd.dish_id JOIN restaurants rs ON rs.id = rd.restaurant_id AND rs.city_id = pg.city_id AND rs.is_active = true WHERE rd.status IN ('approved_by_admin', 'verified_by_owner') AND ((pg.is_hub AND dd.dish_group = pg.canon) OR (NOT pg.is_hub AND dd.canonical_slug = pg.canon))) x ON true) SELECT c.page_slug, min(c.dish_name), (count(*) FILTER (WHERE c.rt > r.rt OR (c.rt = r.rt AND c.id < r.id)) + 1)::int, count(*)::int FROM comp c, r GROUP BY c.page_slug HAVING bool_or(c.id = r.id) ORDER BY 3, 4 DESC, 1 LIMIT 50; $$;
REVOKE ALL ON FUNCTION public.restaurant_positions(text) FROM public;
GRANT EXECUTE ON FUNCTION public.restaurant_positions(text) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.homepage_cities() RETURNS TABLE (id uuid, name text, slug text, pages int) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT c.id, c.name, c.slug, count(*)::int FROM public.cities c JOIN public.seo_landing_pages p ON p.city_id = c.id AND p.is_active JOIN public.landing_page_counts n ON n.page_slug = p.slug AND n.restaurant_count >= 6 WHERE c.is_active GROUP BY c.id, c.name, c.slug ORDER BY 4 DESC, 2 $$;
GRANT EXECUTE ON FUNCTION public.homepage_cities() TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.nearest_city(p_lat double precision, p_lng double precision) RETURNS TABLE (id uuid, name text, slug text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT c.id, c.name, c.slug FROM public.restaurants r JOIN public.cities c ON c.id = r.city_id AND c.is_active WHERE r.is_active AND r.geo_lat IS NOT NULL AND r.geo_lng IS NOT NULL AND p_lat BETWEEN 50 AND 54 AND p_lng BETWEEN 3 AND 8 ORDER BY (r.geo_lat - p_lat) ^ 2 + ((r.geo_lng - p_lng) * cos(radians(p_lat))) ^ 2 LIMIT 1 $$;
GRANT EXECUTE ON FUNCTION public.nearest_city(double precision, double precision) TO anon, authenticated;